// #6a993d6ab2e4b167537ea9a3 — AC5: рекрутёр (user) не может поставить решение и заметку по ЧУЖОМУ кандидату;
// данные кандидата не меняются. Кейс CAND-009.
// Чужой кандидат — QA_FOREIGN_CANDIDATE, по умолчанию QA-N16-6e5ece-kbd-1436 (назначен другому, проверен вручную 14.10).
// Сервер блокирует обе записи (решение — RLS: 200 и 0 строк; заметка — 403) → ничего не меняется → @prod-safe.
// Если запрет сломается, тест упадёт на ответе записи, а контроль менеджера покажет, что именно изменилось.
import { test, expect } from '../../fixtures';
import { openWithApi, runStamp } from '../support/api';
import { HIRING, TXT, addNote, candidateId, getReport, listCandidates, setDecision } from './hiring-support';

const FOREIGN = process.env.QA_FOREIGN_CANDIDATE || 'QA-N16-6e5ece-kbd-1436';

test.describe('Кандидаты — решение и заметка по чужому кандидату (#6a993d6ab2e4b167537ea9a3)', () => {
  test('рекрутёр: чужого кандидата нет в списке, отчёт «המועמד לא נמצא», решение (200 []) и заметка (403) блокируются, данные не меняются @desktop @prod-safe #6a993d6ab2e4b167537ea9a3', async ({ asUser }) => {
    // Исходное состояние — глазами менеджера.
    const business = await asUser('business');
    const bizApi = await openWithApi(business, '/candidates');
    const id = await candidateId(bizApi, FOREIGN);
    const before = await getReport(bizApi, id);

    const recruiter = await asUser('user');
    const recApi = await openWithApi(recruiter, '/candidates');
    // Источник: треб.5 — запись не назначена рекрутёру: ни в списке, ни в отчёте.
    expect((await listCandidates(recApi)).map((c) => c.id), `«${FOREIGN}» назначен рекрутёру — нужен чужой (QA_FOREIGN_CANDIDATE)`).not.toContain(id);
    await recruiter.goto(`/candidates/${id}/report`);
    await expect(recruiter.getByRole('heading', { name: TXT.notFound })).toBeVisible();
    await expect(recruiter.getByTestId('hiring-decision')).toHaveCount(0);
    await expect(recruiter.getByTestId('internal-note')).toHaveCount(0);

    // Источник: AC5 — «בהינתן משתמש ללא הרשאה לרשומה, כאשר הוא מנסה לעדכן סטטוס, אז הפעולה נחסמת».
    const target = (Object.keys(HIRING) as (keyof typeof HIRING)[]).find((s) => s !== before.hiring?.status)!;
    const dec = await setDecision(recApi, id, target);
    expect(dec.status(), await dec.text()).toBe(200);
    expect(await dec.json(), 'RLS должен вернуть 0 строк (UI → «אין לכם הרשאה…»)').toEqual([]);

    const probe = `QA-AUTO-AC5-PROBE-${runStamp()} — запись рекрутёра по чужому кандидату должна блокироваться`;
    const note = await addNote(recApi, id, probe, before.report?.id ?? null);
    expect(note.status(), await note.text()).toBe(403);
    expect(await note.json()).toMatchObject({ code: '42501', message: 'forbidden' });

    // Контроль: у менеджера всё как было.
    const after = await getReport(bizApi, id);
    expect(after.hiring, 'решение чужого кандидата изменилось').toEqual(before.hiring);
    expect((after.notes ?? []).map((n) => n.body)).toEqual((before.notes ?? []).map((n) => n.body));
    expect((after.notes ?? []).some((n) => n.body === probe), 'проба заметки сохранилась').toBe(false);
  });
});
